  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 13, $j$4.1 Formal Commands with Usted and Ustedes$j$, $j${"readings": [{"title": "Matthew 11 (King James Version)", "url": "/portal/bible/Matthew/11"}], "body": "Matthew 11:28 says, Come unto me, all ye that labour and are heavy laden, and I will give you rest. This verse is a command, and commands are how we give directions, invite and serve. In Spanish, you speak politely to a pastor, a teacher or a stranger with the formal commands, usted for one person and ustedes for more than one.\n\nTo form them, start with the yo form of the present tense, drop the o, and add the opposite vowel. Ar verbs take e and en. Er and ir verbs take a and an. Hablar becomes hable and hablen. Comer becomes coma and coman. Escribir becomes escriba and escriban. Verbs with an irregular yo form keep it: tener, tengo, tenga; hacer, hago, haga; venir, vengo, venga; decir, digo, diga.\n\nSpelling changes keep the sound: buscar becomes busque, pagar becomes pague and empezar becomes empiece. Five verbs are completely irregular: ser, sea; ir, vaya; estar, esté; dar, dé; saber, sepa.\n\nFor the negative, put no before the command. Pronouns attach to an affirmative command and go before a negative one. Siéntese, por favor. No se siente. Dígame la verdad.\n\nWorked example: Pase, siéntese y abra su Biblia. Venga con nosotros. Common mistake: using the infinitive as a command or forgetting the accent when a pronoun is attached. Siéntese needs the accent.\n\nYour task: (1) Write the usted and ustedes commands for hablar, comer, escribir and venir. (2) Write six polite commands a greeter at church might say.\n\nFlorida standards: Florida World Languages standards, Level 2 (WL.K12.NH, WL.K12.IL).", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "Florida World Languages standards, Level 2 (WL.K12.NH, WL.K12.IL)", "script": "Welcome back. Listen, Matthew 11:28 says, Come unto me, all ye that labour and are heavy laden, and I will give you rest. That is a command.\n\nNow watch this. Formal commands are for usted and ustedes. Start with the yo form, drop the o, add the opposite vowel. Ar verbs take e, en. Er and ir verbs take a, an. Hable, coma, escriba. Hablen, coman, escriban.\n\nIrregular yo forms carry over. Tenga, haga, venga, diga.\n\nFive verbs are irregular: sea, vaya, esté, dé, sepa.\n\nPronouns attach to affirmative commands. Siéntese. Dígame. For a negative, the pronoun goes before. No se siente.\n\nYour task is to write formal commands for four verbs and six polite church commands. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$4.1 Formal Commands with Usted and Ustedes$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 14, $j$4.2 Informal Commands with Tú$j$, $j${"readings": [{"title": "Proverbs 3 (King James Version)", "url": "/portal/bible/Proverbs/3"}], "body": "Proverbs 3:5 says, Trust in the LORD with all thine heart; and lean not unto thine own understanding. The first half is a positive command and the second is a negative command. With friends, family and children, Spanish uses tú commands.\n\nThe affirmative tú command is the same as the él form of the present tense. Habla, come, escribe. Habla más despacio. Come tu desayuno. Eight common verbs are irregular in the affirmative: decir, di; hacer, haz; ir, ve; poner, pon; salir, sal; ser, sé; tener, ten; venir, ven. Ven a la iglesia. Haz tu tarea. Di la verdad.\n\nThe negative tú command uses the usted pattern with an s: take the yo form, drop the o, and add the opposite vowel plus s. No hables, no comas, no escribas. Irregular negatives are no vayas, no seas, no des, no estés. No tengas miedo. No digas mentiras.\n\nPronouns attach to the affirmative and go before the negative: Dime la verdad, no me mientas. Hazlo ahora, pero no lo hagas con prisa.\n\nWorked example: Confía en el Señor y no te preocupes. Lee tu Biblia, escucha a tus padres y no dejes de orar. Common mistake: using the tú command with an elder. Use usted commands with pastors, teachers and strangers.\n\nYour task: (1) Give the affirmative and negative tú commands for hablar, comer, hacer and ir. (2) Write six pieces of advice for a younger cousin.\n\nFlorida standards: Florida World Languages standards, Level 2 (WL.K12.NH, WL.K12.IL).", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "Florida World Languages standards, Level 2 (WL.K12.NH, WL.K12.IL)", "script": "Welcome back. Listen, Proverbs 3:5 says, Trust in the LORD with all thine heart; and lean not unto thine own understanding. A positive command and a negative command in one verse.\n\nNow watch this. The affirmative tú command is the él form. Habla, come, escribe.\n\nEight irregular affirmatives: di, haz, ve, pon, sal, sé, ten, ven.\n\nThe negative tú command takes the yo form, drops the o and adds the opposite vowel plus s. No hables, no comas, no escribas. Irregulars: no vayas, no seas, no des, no estés.\n\nPronouns attach to affirmative commands and go before negative ones. Dime la verdad. No me mientas.\n\nUse tú with friends and family, and usted with elders.\n\nYour task is to give affirmative and negative commands and write six pieces of advice. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$4.2 Informal Commands with Tú$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 15, $j$4.3 Travel, Transportation and Directions$j$, $j${"readings": [{"title": "Psalm 121 (King James Version)", "url": "/portal/bible/Psalms/121"}], "body": "Psalm 121:8 says, The LORD shall preserve thy going out and thy coming in from this time forth, and even for evermore. Travel vocabulary helps you serve visitors and prepare for missions, trips and work.\n\nKey nouns are el aeropuerto (airport), la estación (station), el autobús (bus), el tren (train), el avión (airplane), el boleto (ticket), el pasaporte (passport), la maleta (suitcase), el vuelo (flight), el hotel (hotel), la reservación (reservation), la salida (departure or exit) and la llegada (arrival).\n\nUseful questions are ¿Dónde está la estación? ¿Cómo llego al aeropuerto? ¿A qué hora sale el vuelo? ¿Cuánto cuesta el boleto? A polite request uses quisiera: Quisiera comprar un boleto, por favor. Quisiera reservar una habitación.\n\nDirections use commands. Siga derecho means keep going straight. Doble a la derecha means turn right. Doble a la izquierda means turn left. Cruce la calle means cross the street. Está al lado de, enfrente de, cerca de and lejos de tell where a place is. Está a dos cuadras means it is two blocks away.\n\nWorked example: Perdón, ¿cómo llego al hotel? Siga derecho dos cuadras y doble a la izquierda. Está enfrente de la iglesia. Common mistake: using tú commands with a stranger. Use usted: siga, doble, cruce.\n\nYour task: (1) Write a dialogue of eight lines in which a visitor asks directions to your church. (2) List ten travel words with their meanings.\n\nFlorida standards: Florida World Languages standards, Level 2 (WL.K12.NH, WL.K12.IL).", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "Florida World Languages standards, Level 2 (WL.K12.NH, WL.K12.IL)", "script": "Welcome back. Listen, Psalm 121:8 says, The LORD shall preserve thy going out and thy coming in from this time forth, and even for evermore. Let us learn the language of travel.\n\nNow watch this. Key words: el aeropuerto, la estación, el autobús, el tren, el boleto, el pasaporte, la maleta, el vuelo, el hotel, la reservación.\n\nQuestions: ¿Dónde está la estación? ¿Cómo llego al aeropuerto? ¿A qué hora sale el vuelo? Be polite with quisiera. Quisiera comprar un boleto.\n\nDirections use usted commands. Siga derecho. Doble a la derecha. Doble a la izquierda. Cruce la calle.\n\nPlaces: al lado de, enfrente de, cerca de, lejos de. Está a dos cuadras.\n\nYour task is to write a dialogue about directions to your church and list ten travel words. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$4.3 Travel, Transportation and Directions$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 16, $j$4.4 Health, the Pharmacy and Emergencies$j$, $j${"readings": [{"title": "James 5 (King James Version)", "url": "/portal/bible/James/5"}], "body": "James 5:14 says, Is any sick among you? let him call for the elders of the church; and let them pray over him, anointing him with oil in the name of the Lord. The church has always cared for the sick, and Spanish helps you comfort and assist neighbors.\n\nReview the body and add symptoms. Tengo fiebre means I have a fever. Tengo tos means I have a cough. Tengo dolor de cabeza, de garganta, de estómago. Estoy mareado means I am dizzy. Soy alérgico a means I am allergic to. Places and people include la farmacia, la clínica, el hospital, el médico, la enfermera, la receta and la medicina.\n\nUseful phrases are ¿Dónde le duele? ¿Cuánto tiempo hace que está enfermo? Tome una pastilla cada ocho horas. Descanse y beba mucha agua. Formal commands are used because you are speaking with an adult.\n\nIn an emergency, say Es una emergencia. Llame al 911. Necesito ayuda. Hay un accidente. Estoy aquí con usted.\n\nWorked example: Doctor, tengo dolor de garganta y fiebre desde ayer. Common mistake: giving medical advice. A volunteer comforts, listens and calls for help, but does not diagnose or prescribe. For anything serious, call a doctor or 911 and ask for a trained medical interpreter.\n\nYour task: (1) Write a dialogue of eight lines between a patient and a pharmacist. (2) Write five emergency phrases and what each means.\n\nFlorida standards: Florida World Languages standards, Level 2 (WL.K12.NH, WL.K12.IL).", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "Florida World Languages standards, Level 2 (WL.K12.NH, WL.K12.IL)", "script": "Welcome back. Listen, James 5:14 says, Is any sick among you? let him call for the elders of the church. The church cares for the sick, and Spanish helps us do that.\n\nNow watch this. Symptoms: tengo fiebre, tengo tos, tengo dolor de cabeza, de garganta, de estómago. Estoy mareado. Soy alérgico a.\n\nPlaces: la farmacia, la clínica, el hospital. People: el médico, la enfermera. Things: la receta, la medicina.\n\nPhrases: ¿Dónde le duele? Tome una pastilla cada ocho horas. Descanse y beba mucha agua.\n\nIn an emergency: Es una emergencia. Llame al 911. Necesito ayuda.\n\nRemember, a volunteer does not diagnose or prescribe. Call a professional and ask for a trained medical interpreter.\n\nYour task is to write a patient and pharmacist dialogue and five emergency phrases. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$4.4 Health, the Pharmacy and Emergencies$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'assessment', 4, $j$Assessment 4: Commands, Travel and Community$j$, $j${"prompt": "Write a report of at least 300 words in English with Spanish examples. Use complete sentences and label each part. Psalm 121:8 says, The LORD shall preserve thy going out and thy coming in from this time forth, and even for evermore.\n\nPart 1: Explain how to form formal commands and write the usted and ustedes commands for six verbs, including two irregular ones.\nPart 2: Explain how to form affirmative and negative tú commands and write both forms for six verbs, including three irregular ones.\nPart 3: Write a Spanish dialogue of at least ten lines in which a visitor asks for directions to your church, using travel words and formal commands.\nPart 4: Write a Spanish dialogue of at least eight lines at a pharmacy or clinic using symptom words and one emergency phrase.\nPart 5: Explain when a volunteer should call a professional or a trained interpreter, and why.\nPart 6: Explain how James 5:14 and Matthew 25:40 guide the church's care for people in need.", "rubric": "100 points. Part 1: 15 points. Part 2: 20 points. Part 3: 20 points. Part 4: 20 points. Part 5: 10 points. Part 6: 10 points. Conventions: 5 points. A score of 70 or above is passing."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'assessment' and title = $j$Assessment 4: Commands, Travel and Community$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'discussion', 4, $j$Discussion 4: Giving Good Directions$j$, $j${"prompt": "Write a post of at least 120 words that (1) describes a time someone helped you find your way or you helped someone else, (2) shares at least three Spanish commands or directions from this unit, and (3) connects your answer to Psalm 121:8 or Proverbs 3:5. Then write a respectful reply of at least 40 words to another student's post, or answer this question: Why do we use a formal command with an elder and an informal command with a friend?"}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'discussion' and title = $j$Discussion 4: Giving Good Directions$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 16, $j$Check 4.1: Formal Commands with Usted and Ustedes$j$, $j${"questions": [{"q": "The usted command of hablar is:", "options": ["Hablar", "Habla", "Hablas", "Hable"]}, {"q": "The usted command of venir is:", "options": ["Venie", "Vienga", "Viene", "Venga"]}, {"q": "Siéntese means:", "options": ["I sit", "Sit them", "Sit down", "Do not sit"]}, {"q": "The usted command of ser is:", "options": ["Sé", "Es", "Sea", "Sera"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 4.1: Formal Commands with Usted and Ustedes$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{3,3,2,2}'::int[], array[$j$Ar verbs take e in the formal command.$j$,$j$The yo form vengo gives venga.$j$,$j$Sentarse in an affirmative formal command.$j$,$j$Sea is irregular.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 4.1: Formal Commands with Usted and Ustedes$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 17, $j$Check 4.2: Informal Commands with Tú$j$, $j${"questions": [{"q": "The affirmative tú command of hablar is:", "options": ["Habla", "Hable", "Hables", "Hablas"]}, {"q": "The affirmative tú command of hacer is:", "options": ["Hagas", "Hazo", "Hace", "Haz"]}, {"q": "The negative tú command of comer is:", "options": ["No comes", "No comas", "No coma", "No come"]}, {"q": "The negative tú command of ir is:", "options": ["No vaya", "No vayas", "No vas", "No ve"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 4.2: Informal Commands with Tú$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{0,3,1,1}'::int[], array[$j$It matches the él form.$j$,$j$Hacer is irregular and becomes haz.$j$,$j$Negative tú commands use the opposite vowel plus s.$j$,$j$Ir is irregular in the negative.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 4.2: Informal Commands with Tú$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 18, $j$Check 4.3: Travel, Transportation and Directions$j$, $j${"questions": [{"q": "Doble a la izquierda means:", "options": ["Turn left", "Stop", "Turn right", "Go straight"]}, {"q": "El boleto is:", "options": ["The passport", "The bus", "The ticket", "The suitcase"]}, {"q": "Quisiera comprar un boleto is:", "options": ["A question about time", "A polite request", "A command", "A past event"]}, {"q": "Está enfrente de la iglesia means:", "options": ["It is inside the church", "It is across from the church", "It is far from the church", "It was the church"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 4.3: Travel, Transportation and Directions$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{0,2,1,1}'::int[], array[$j$Izquierda means left.$j$,$j$Boleto means ticket.$j$,$j$Quisiera makes a request polite.$j$,$j$Enfrente de means across from or opposite.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 4.3: Travel, Transportation and Directions$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 19, $j$Check 4.4: Health, the Pharmacy and Emergencies$j$, $j${"questions": [{"q": "Tengo dolor de cabeza means:", "options": ["I have a fever", "I have a headache", "I have a cold", "I am dizzy"]}, {"q": "Llame al 911 is a:", "options": ["Formal command", "Past tense", "Question", "Informal command"]}, {"q": "La receta is the:", "options": ["Prescription", "Pharmacy", "Nurse", "Pill"]}, {"q": "A church volunteer should:", "options": ["Diagnose illness", "Prescribe medicine", "Avoid helping", "Call a professional for serious needs"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 4.4: Health, the Pharmacy and Emergencies$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{1,0,0,3}'::int[], array[$j$Dolor de cabeza is headache.$j$,$j$Llame is the usted command of llamar.$j$,$j$Receta means prescription or recipe.$j$,$j$Volunteers comfort and call for help.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 4.4: Health, the Pharmacy and Emergencies$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 20, $j$Unit Quiz 4: Commands, Travel and Community$j$, $j${"questions": [{"q": "The usted command of comer is:", "options": ["Comes", "Comer", "Come", "Coma"]}, {"q": "The usted command of tener is:", "options": ["Tengues", "Tené", "Tiene", "Tenga"]}, {"q": "The affirmative tú command of venir is:", "options": ["Ven", "Vienes", "Venga", "Viene"]}, {"q": "The negative tú command of hablar is:", "options": ["No hables", "No hable", "No hablar", "No habla"]}, {"q": "Siga derecho means:", "options": ["Stop", "Turn right", "Keep going straight", "Cross the street"]}, {"q": "El pasaporte is a:", "options": ["Ticket", "Flight", "Passport", "Suitcase"]}, {"q": "Soy alérgico a means:", "options": ["I am angry at", "I am allergic to", "I am sick with", "I am tired of"]}, {"q": "A volunteer who sees a serious injury should:", "options": ["Call 911", "Wait a day", "Give medicine", "Ignore it"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Unit Quiz 4: Commands, Travel and Community$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{3,3,0,0,2,2,1,0}'::int[], array[$j$Er verbs take a in the formal command.$j$,$j$Tengo gives tenga.$j$,$j$Ven is irregular.$j$,$j$Negative tú commands end in es for ar verbs.$j$,$j$Derecho means straight ahead.$j$,$j$Pasaporte means passport.$j$,$j$Alérgico a means allergic to.$j$,$j$Call for professional help.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Unit Quiz 4: Commands, Travel and Community$j$ on conflict (item_id) do nothing;
